<?php
declare(strict_types=1);

require_once __DIR__ . '/types.php';

/**
 * CYK parser for grammars in Chomsky Normal Form.
 */
final class CYKParser
{
    /** @var Grammar */
    private Grammar $grammar;

    /** @var array<string,array<int,string>> RHS‑to‑LHS index */
    private array $rhsIndex;

    /**
     * @param Grammar $grammar
     */
    public function __construct(Grammar $grammar)
    {
        $this->grammar  = $grammar;
        $this->rhsIndex = $grammar->buildRhsIndex();
    }

    /**
     * Determines whether $input belongs to the language generated by the grammar.
     *
     * @param string $input  Input string consisting of terminal symbols (each symbol is a single character)
     * @return bool
     */
    public function parse(string $input): bool
    {
        $n = strlen($input);
        if ($n === 0) {
            // Accept iff the start symbol can derive ε
            return in_array($this->grammar->startSymbol, $this->rhsIndex[''] ?? [], true);
        }

        // table[i][j] = set of non‑terminals that derive substring of length j+1 starting at i
        $table = array_fill(0, $n, array_fill(0, $n, []));

        // Fill the diagonal with productions that produce the terminals
        for ($i = 0; $i < $n; $i++) {
            $terminal = $input[$i];
            $key = $terminal; // RHS key for a single terminal
            $table[$i][0] = $this->rhsIndex[$key] ?? [];
        }

        // Fill the upper triangle of the table
        for ($length = 2; $length <= $n; $length++) {          // length of the span
            for ($start = 0; $start <= $n - $length; $start++) { // start index of the span
                $cellNonTerminals = [];
                // split the span into two parts
                for ($partition = 1; $partition < $length; $partition++) {
                    $leftSet  = $table[$start][$partition - 1];
                    $rightSet = $table[$start + $partition][$length - $partition - 1];
                    foreach ($leftSet as $B) {
                        foreach ($rightSet as $C) {
                            $key = $B . ' ' . $C;
                            if (isset($this->rhsIndex[$key])) {
                                foreach ($this->rhsIndex[$key] as $A) {
                                    $cellNonTerminals[$A] = true;
                                }
                            }
                        }
                    }
                }
                $table[$start][$length - 1] = array_keys($cellNonTerminals);
            }
        }

        // The string is in the language iff the start symbol appears in the top‑right cell
        return in_array($this->grammar->startSymbol, $table[0][$n - 1], true);
    }
}
